/*\
title: $:/plugins/huwiki/ai/model-adapters.js
type: application/javascript
module-type: library

Provider-neutral HTTP adapters. No API keys or external code dependencies.
\*/
(function(){
"use strict";
var PROVIDERS={
  ollama:{label:"Ollama · lokal modelserver",defaultUrl:"http://127.0.0.1:11434",modelsPath:"/api/tags",chatPath:"/api/chat"},
  lmstudio:{label:"LM Studio · OpenAI-kompatibel",defaultUrl:"http://127.0.0.1:1234",modelsPath:"/v1/models",chatPath:"/v1/chat/completions"}
};
PROVIDERS.compatible=PROVIDERS.lmstudio;
var CLOUD={openai:"OpenAI",gemini:"Google Gemini",claude:"Anthropic Claude"};
function isCloud(provider){return Object.prototype.hasOwnProperty.call(CLOUD,provider);}
function supportedProvider(provider){return isCloud(provider)||Object.prototype.hasOwnProperty.call(PROVIDERS,provider);}
function providerLabel(provider){return isCloud(provider)?CLOUD[provider]:config(provider).label;}
function config(provider){if(!Object.prototype.hasOwnProperty.call(PROVIDERS,provider))throw new Error("Ukendt AI-motor: "+provider);return PROVIDERS[provider];}
function normalizeUrl(s){
  s=String(s||"").trim().replace(/\/+$/g,"");
  if(!/^https?:\/\//i.test(s)) throw new Error("Serveradressen skal starte med http:// eller https://.");
  if(/[\s<>]/.test(s)) throw new Error("Serveradressen indeholder ugyldige tegn.");
  // This widget intentionally accepts only a server root. Prevent doubled API paths.
  if(/\/(?:api|v1)(?:\/|$)/.test(s)) throw new Error("Angiv serveradressen uden /api eller /v1.");
  return s;
}
function modelsEndpoint(provider,url){return normalizeUrl(url)+config(provider).modelsPath;}
function chatEndpoint(provider,url){return normalizeUrl(url)+config(provider).chatPath;}
function parseModels(provider,payload){
  config(provider);
  var items=provider==="ollama"?(payload&&payload.models):(payload&&payload.data);
  if(!Array.isArray(items))throw new Error("Serveren returnerede ikke en forventet modelliste.");
  return items.map(function(item){return item && (provider==="ollama"?item.name:item.id);})
    .filter(function(n){return typeof n==="string"&&n.trim().length>0;});
}
function preferModel(models,current){
  if(!Array.isArray(models)||!models.length)return "";
  if(current&&models.indexOf(current)!==-1)return current;
  var usable=models.filter(function(s){return !/embed|rerank|whisper|speech-to-text|tts/i.test(s);});
  if(!usable.length)usable=models;
  for(var i=0;i<usable.length;i++)if(/gemma.?4/i.test(usable[i]))return usable[i];
  return usable[0];
}
// Cloud catalogs are not ordered by suitability for an ordinary text chat.
function preferCloudModel(provider,models,current){
  if(!Array.isArray(models)||!models.length)return "";
  if(current&&models.indexOf(current)>=0)return current;
  if(provider==="gemini"){
    var candidates=models.filter(function(id){return /gemini.*flash/i.test(id)&&!/image|audio|tts|live/i.test(id);});
    candidates.sort(function(a,b){
      var previewA=/preview|experimental/i.test(a),previewB=/preview|experimental/i.test(b);
      if(previewA!==previewB)return Number(previewA)-Number(previewB);
      var av=a.match(/gemini-(\d+)(?:\.(\d+))?/i),bv=b.match(/gemini-(\d+)(?:\.(\d+))?/i);
      var an=av?Number(av[1])*100+Number(av[2]||0):0,bn=bv?Number(bv[1])*100+Number(bv[2]||0):0;
      return bn-an;
    });
    return candidates[0]||models[0];
  }
  if(provider==="openai")return models.find(function(id){return /^(?:gpt-5-mini|gpt-4\.1-mini|gpt-4o-mini)$/.test(id);})||models[0];
  return preferModel(models,current);
}
// Images are browser-only until user explicitly saves a media tiddler.
// Wire format differs across Ollama and OpenAI-compatible local servers.
function withImageAttachments(provider,messages,images){
  config(provider);
  var copied=messages.map(function(m){return {role:m.role,content:m.content};});
  if(!images || !images.length)return copied;
  var i=copied.length-1;
  while(i>=0 && copied[i].role!=="user")i--;
  if(i<0)throw new Error("Ingen brugerbesked til billedanalysen.");
  var msg=copied[i];
  if(provider==="ollama") {
    msg.images=images.map(function(im){return im.data;});
  } else {
    msg.content=[{type:"text",text:String(msg.content||"")}].concat(images.map(function(im){return {
      type:"image_url",image_url:{url:"data:"+im.mimeType+";base64,"+im.data}
    };}));
  }
  return copied;
}
// LM Studio's OpenAI-compatible endpoint supports schema-constrained JSON.
// The engine additionally validates titles, tags and the proposal on receipt.
var PLAN_SCHEMA={
  type:"object",additionalProperties:false,
  properties:{
    overview:{type:"object",additionalProperties:false,
      properties:{title:{type:"string"},summary:{type:"string"}},required:["title","summary"]},
    tagChanges:{type:"array",items:{type:"object",additionalProperties:false,
      properties:{title:{type:"string"},addTags:{type:"array",items:{type:"string"}},reason:{type:"string"}},
      required:["title","addTags","reason"]}}
  },required:["overview","tagChanges"]
};
// Request budgets: shorter image analysis by default helps slow local vision models.
// Users can still ask follow-up questions when they need a detailed answer.
function hasVisionInput(messages){
  return (messages||[]).some(function(m){return !!(m.images&&m.images.length) ||
    (Array.isArray(m.content)&&m.content.some(function(p){return p.type==='image_url';}));});
}
function timingFromResponse(provider,payload){
  var usage=payload&&payload.usage||{},result={};
  if(provider==='ollama'){
    if(Number.isFinite(Number(payload&&payload.total_duration))&&Number(payload.total_duration)>0)
      result.serverMs=Math.round(Number(payload.total_duration)/1e6);
    if(Number.isFinite(Number(payload&&payload.eval_duration))&&Number(payload.eval_duration)>0)
      result.generationMs=Math.round(Number(payload.eval_duration)/1e6);
    if(Number.isFinite(Number(payload&&payload.prompt_eval_duration))&&Number(payload.prompt_eval_duration)>0)
      result.promptMs=Math.round(Number(payload.prompt_eval_duration)/1e6);
    if(Number(payload&&payload.eval_count)>0)result.outputTokens=Math.round(Number(payload.eval_count));
    if(Number(payload&&payload.prompt_eval_count)>0)result.inputTokens=Math.round(Number(payload.prompt_eval_count));
  }else {
    if(Number(usage.completion_tokens)>0)result.outputTokens=Math.round(Number(usage.completion_tokens));
    if(Number(usage.prompt_tokens)>0)result.inputTokens=Math.round(Number(usage.prompt_tokens));
  }
  return result;
}
function completionRequest(provider,model,messages,mode){
  config(provider);
  if(!model||typeof model!=="string")throw new Error("Vælg en AI-model først.");
  if(!Array.isArray(messages)||!messages.length)throw new Error("Ingen tiddlere at analysere.");
  var isChat=mode==="chat",vision=isChat&&hasVisionInput(messages);
  var chatBudget=vision?1100:2400;
  if(provider==="ollama")return {model:model,messages:messages,stream:false,
    format:isChat?undefined:"json",options:{temperature:isChat?0.6:0.2,num_predict:isChat?chatBudget:2400}};
  if(isChat)return {model:model,messages:messages,stream:false,temperature:0.6,max_tokens:chatBudget};
  return {model:model,messages:messages,stream:false,temperature:0.2,max_tokens:2400,
    response_format:{type:"json_schema",json_schema:{name:"huwiki_change_proposal",strict:true,schema:PLAN_SCHEMA}}};
}
function parseCompletion(provider,payload){
  config(provider);
  var m=provider==="ollama" ? payload&&payload.message : payload&&payload.choices&&payload.choices[0]&&payload.choices[0].message;
  var c=m&&m.content;
  if(Array.isArray(c))c=c.filter(function(x){return x&&x.type==="text";}).map(function(x){return x.text||"";}).join("\n");
  if(typeof c!=="string" || !c.trim())throw new Error("Modellen returnerede ikke tekst til ændringsforslaget.");
  return c;
}
function parsePlanJSON(value){
  var source=String(value||"").trim();
  // Accept fenced JSON from models that don't implement structured output.
  if(/^```/.test(source))source=source.replace(/^```(?:json)?\s*/i,"").replace(/\s*```\s*$/i,"");
  try{return JSON.parse(source);}catch(err){throw new Error("AI-svaret var ikke gyldigt JSON. Prøv analysen igen.");}
}
function explainHttpError(provider,status,body){
  var excerpt=String(body||"").slice(0,250).replace(/\s+/g," ");
  var msg=(provider==="lmstudio"?"LM Studio":"Ollama")+" HTTP "+status;
  if(status===401)msg+=" – serveren kræver godkendelse (understøttes endnu ikke i denne prototype)";
  else if(status===404)msg+=" – kontrollér serveradressen og API-stien";
  else if(status===400||status===422)msg+=" – modellen eller JSON-formatet blev afvist";
  return msg+(excerpt?": "+excerpt:"");
}
exports.hasVisionInput=hasVisionInput;
exports.timingFromResponse=timingFromResponse;
exports.withImageAttachments=withImageAttachments;
exports.config=config;
exports.isCloud=isCloud;
exports.supportedProvider=supportedProvider;
exports.providerLabel=providerLabel;
exports.normalizeUrl=normalizeUrl;
exports.modelsEndpoint=modelsEndpoint;
exports.chatEndpoint=chatEndpoint;
exports.parseModels=parseModels;
exports.preferModel=preferModel;
exports.preferCloudModel=preferCloudModel;
exports.completionRequest=completionRequest;
exports.parseCompletion=parseCompletion;
exports.parsePlanJSON=parsePlanJSON;
exports.explainHttpError=explainHttpError;
})();
